def _show_sitk(img):
  import matplotlib.pyplot as plt
  arr = sitk.GetArrayFromImage(img)
  dpi = plt.rcParams['figure.dpi']
  fig = plt.figure(figsize=(arr.shape[1]/dpi, arr.shape[0]/dpi))
  plt.imshow(arr, cmap='gray')
  plt.axis('off')
  plt.show()

import SimpleITK as sitk
from SimpleITK import Image as SImage

i = sitk.ReadImage(files[2])

_show_sitk(i)

def _grayscale_simg(img: sitk.Image) -> sitk.Image:
  r = sitk.VectorIndexSelectionCast(img, 0, sitk.sitkFloat32)
  g = sitk.VectorIndexSelectionCast(img, 1, sitk.sitkFloat32)
  b = sitk.VectorIndexSelectionCast(img, 2, sitk.sitkFloat32)
  gs = 0.299 * r + 0.587 * g + 0.114 * b
  scalar_type = sitk.VectorIndexSelectionCast(img, 0).GetPixelID()
  return sitk.Cast(gs, scalar_type)

ig = _grayscale_simg(i)

_show_sitk(ig)

ig.GetNumberOfComponentsPerPixel()

from radiomics import featureextractor

def _get_dummy_mask(img) -> SImage:
  m = np.ones(img.GetSize()[::-1], dtype=np.uint8)
  ms = sitk.GetImageFromArray(m)
  ms.CopyInformation(img)
  # _show_sitk(ms)
  return ms

m = _get_dummy_mask(ig)

params = {
    'setting': {
        'binWidth': 25,
        'resampledPixelSpacing': None,   # or [1.0, 1.0] if you want spacing
        'force2D': True,
        'shape2D': True
    }
}
xtractor = featureextractor.RadiomicsFeatureExtractor(**params)
xtractor.enableFeatureClassByName('firstorder')
xtractor.enableFeatureClassByName('glcm')
xtractor.enableFeatureClassByName('glrlm')
xtractor.enableFeatureClassByName('glszm')
xtractor.enableFeatureClassByName('ngtdm')
xtractor.enableFeatureClassByName('gldm')

f = xtractor.execute(ig, m) ; f

pd.Series({k: v for k,v in f.items() if not k.startswith('diagnostics_')})

"""Okay let's loop all this logic"""

len(files)

from tqdm.notebook import tqdm

from fastcore.parallel import parallel

def extract_features_for_file(f):
  lbl = f.parent.name
  i = sitk.ReadImage(f)
  ig = _grayscale_simg(i)
  m = _get_dummy_mask(ig)
  features = xtractor.execute(ig, m)
  features = pd.Series({k: v for k,v in features.items() if not k.startswith('diagnostics_')})
  features['label'] = lbl
  return pd.Series(features)

import os
n_workers = os.cpu_count() - 1; n_workers

rows = parallel(extract_features_for_file, files, n_workers=n_workers, progress=True)

df = pd.DataFrame(rows) ; df.head()

df.shape

